begin;
create temp table _kb_fix(node_id integer primary key, blocks jsonb not null, search_text text not null) on commit drop;
insert into _kb_fix values (42, $kbfix$[{"t":"list","id":"a1-1-1-3-b1","imp":"core","items":["1、==内存储器、外存储器与系统总线概述==：","^^1）内存储器^^：==计算机的内存储器是指 ROM 和 RAM==，它是外存与 CPU 进行沟通的桥梁，计算机中所有程序的运行都在内存中进行。内存性能的强弱影响计算机整体发挥的水平。内存也称内存储器和主存储器，用于暂时存放 CPU 中的运算数据以及与硬盘等外部存储器交换的数据。","^^2）外存储器^^：==指除计算机内存及 CPU 缓存以外的储存器，此类储存器一般断电后仍然能保存数据。==","^^3）系统总线^^：==总线是连接各个部件的信息传输线，是各个部件共享的传输介质。==总线结构的计算机举例：单总线结构框图、面向 CPU 的双总线结构框图、以存储器为中心的双总线结构框图。","2、==内存储器与外存储器的区别==：存储器分为==内存储器和外存储器==。外存不直接影响计算机的运行速度，影响计算机速度的主要是 CPU 和内存。 内存：运行速度快，断电后信息消失，存储容量小，由半导体芯片构成，可直接与 CPU 交换数据。 外存：运行速度慢，断电后信息不丢失，存储容量大，由磁性介质、光学介质或闪存芯片构成，不能直接与 CPU 交换数据，需先调入内存。 存储器的存取时间是指从 CPU 给出存储器地址开始，到存储器读出数据并送到 CPU（或把 CPU 的数据写入存储器）所需要的时间。","3、==主存储器的功能与原理==：主存是 CPU 可直接访问的存储器，用于==存放供 CPU 处理的指令和数据==。 特点：","- ==以字节为单位进行连续编址==，每个存储单元为 1 个字节（8 个二进位）。","- ^^存储容量^^：==主存储器中所包含的存储单元的总数（单位 MB 或 GB）==。","- ^^存取时间^^：==从 CPU 送出内存单元的地址码开始==，到主存读出数据并送到 CPU（或把 CPU 数据写入主存）所需要的时间，单位 ns，1 ns 10⁻⁹ s。","4、==存储器的层状塔式结构==：==内存储器和外存储器组成一个层状的塔式结构==。","1）目的：优化存储器的性能价格比。","2）存储器按读写速度由高到低排列：Cache、RAM、硬盘、光盘。","5、==总线==用于==连接 CPU、内存、外存和各种 I/O 设备并在它们之间传输信息的一组共享的传输线及其控制电路。==","（1）==CPU 总线（前端总线）==：用于连接CPU 和主存之间的总线。一般CPU 总线的数据线条目为CPU 位数。目前CPU(i3/i5/i7/i9）都是64 位。","（2）==I/O 总线==：用于连接主存和I/O 设备（包括外设）总线（目前使用的PCI 和PCI-E）","（3）按总线功能或信号类型分为：==地址总线（传输地址信号）、数据总线（传输数据信号）、控制总线（传输控制信号）。==","①、^^数据总线用于传送数据信息。^^数据总线是双向三态形式的总线，它既可以把CPU 的数据传送到存储器或I/O 接口等其他部件，也可以将其他部件的数据传送到CPU。数据总线的位数是微型计算机的一个重要指标，通常与微处理器的字长相一致。","②、^^地址总线是专门用来传送地址的，^^由于地址只能从 CPU 传向外部存储器或：I/O 端口，所以地址总线总是单向三态的，这与数据总线不同。==地址总线的位数决定了 CPU 可直接寻址的内存空间大小。==例如，8 位微机的地址总线为 16 位，则其最大可寻址空间为 2^16=64KB；16 位微机的地址总线为 20 位，则其可寻址空间为 2^20=1MB。一般来说，@@若地址总线为 n 位，则可寻址空间为 2^n 字节。@@","③、^^控制总线用来传送控制信号和时序信号。^^控制信号中，有的是微处理器送往存储器和I/O 接口电路的，如读/写信号、片选信号、中断响应信号等；也有的是其他部件反馈给CPU 的，如中断申请信号、复位信号、总线请求信号、设备就绪信号等。因此，控制总线的传送方向由具体控制信号而定，一般是双向的。","控制总线的位数要根据系统的实际控制需要而定。","（4）总线带宽：","①、总线带宽指单位时间内总线上可以传输的最大的数据量。","②、@@总线带宽（MB/s）=（总线位宽/8）×总线工作频率（MHz）×每个总线周期数据传输的次数。@@"],"title":"","ordered":false},{"t":"callout","id":"a1-1-1-3-b2","imp":"core","kind":"tip","text":"存储系统按速度由高到低排列为：==寄存器 > 高速缓存 Cache > 内存储器（RAM/ROM） > 外存储器（SSD/机械硬盘/光盘）==；系统总线按传送信号划分为==数据总线（双向传送数据）、地址总线（单向传送物理地址，决定最大寻址空间）、控制总线（双向传送控制/时序信号）==。","title":"考向复习提示：存储层级塔式结构与系统总线分类"},{"t":"callout","id":"a1-1-1-3-b3","imp":"core","kind":"trap","text":"若 CPU 的地址总线为 32 位，则其最大可直接寻址空间为 ==2^32 字节 = 4 GB==；若地址总线为 36 位，最大寻址空间为 ==2^36 字节 = 64 GB==；常考陷阱是将寻址空间误算为“字”而非“字节”，计算机内存始终以==字节（8 位）==为基本编址单位！","title":"高频易错陷阱：地址总线宽度与寻址能力计算"}]$kbfix$::jsonb, $kbfixsearch$A1-1.1.3 计算机内存储器、外存储器概述，系统总线，I/O 总线。 1、内存储器、外存储器与系统总线概述： 1）内存储器：计算机的内存储器是指 ROM 和 RAM，它是外存与 CPU 进行沟通的桥梁，计算机中所有程序的运行都在内存中进行。内存性能的强弱影响计算机整体发挥的水平。内存也称内存储器和主存储器，用于暂时存放 CPU 中的运算数据以及与硬盘等外部存储器交换的数据。 2）外存储器：指除计算机内存及 CPU 缓存以外的储存器，此类储存器一般断电后仍然能保存数据。 3）系统总线：总线是连接各个部件的信息传输线，是各个部件共享的传输介质。总线结构的计算机举例：单总线结构框图、面向 CPU 的双总线结构框图、以存储器为中心的双总线结构框图。 2、内存储器与外存储器的区别：存储器分为内存储器和外存储器。外存不直接影响计算机的运行速度，影响计算机速度的主要是 CPU 和内存。 内存：运行速度快，断电后信息消失，存储容量小，由半导体芯片构成，可直接与 CPU 交换数据。 外存：运行速度慢，断电后信息不丢失，存储容量大，由磁性介质、光学介质或闪存芯片构成，不能直接与 CPU 交换数据，需先调入内存。 存储器的存取时间是指从 CPU 给出存储器地址开始，到存储器读出数据并送到 CPU（或把 CPU 的数据写入存储器）所需要的时间。 3、主存储器的功能与原理：主存是 CPU 可直接访问的存储器，用于存放供 CPU 处理的指令和数据。 特点： - 以字节为单位进行连续编址，每个存储单元为 1 个字节（8 个二进位）。 - 存储容量：主存储器中所包含的存储单元的总数（单位 MB 或 GB）。 - 存取时间：从 CPU 送出内存单元的地址码开始，到主存读出数据并送到 CPU（或把 CPU 数据写入主存）所需要的时间，单位 ns，1 ns 10⁻⁹ s。 4、存储器的层状塔式结构：内存储器和外存储器组成一个层状的塔式结构。 1）目的：优化存储器的性能价格比。 2）存储器按读写速度由高到低排列：Cache、RAM、硬盘、光盘。 5、总线用于连接 CPU、内存、外存和各种 I/O 设备并在它们之间传输信息的一组共享的传输线及其控制电路。 （1）CPU 总线（前端总线）：用于连接CPU 和主存之间的总线。一般CPU 总线的数据线条目为CPU 位数。目前CPU(i3/i5/i7/i9）都是64 位。 （2）I/O 总线：用于连接主存和I/O 设备（包括外设）总线（目前使用的PCI 和PCI-E） （3）按总线功能或信号类型分为：地址总线（传输地址信号）、数据总线（传输数据信号）、控制总线（传输控制信号）。 ①、数据总线用于传送数据信息。数据总线是双向三态形式的总线，它既可以把CPU 的数据传送到存储器或I/O 接口等其他部件，也可以将其他部件的数据传送到CPU。数据总线的位数是微型计算机的一个重要指标，通常与微处理器的字长相一致。 ②、地址总线是专门用来传送地址的，由于地址只能从 CPU 传向外部存储器或：I/O 端口，所以地址总线总是单向三态的，这与数据总线不同。地址总线的位数决定了 CPU 可直接寻址的内存空间大小。例如，8 位微机的地址总线为 16 位，则其最大可寻址空间为 2^16=64KB；16 位微机的地址总线为 20 位，则其可寻址空间为 2^20=1MB。一般来说，若地址总线为 n 位，则可寻址空间为 2^n 字节。 ③、控制总线用来传送控制信号和时序信号。控制信号中，有的是微处理器送往存储器和I/O 接口电路的，如读/写信号、片选信号、中断响应信号等；也有的是其他部件反馈给CPU 的，如中断申请信号、复位信号、总线请求信号、设备就绪信号等。因此，控制总线的传送方向由具体控制信号而定，一般是双向的。 控制总线的位数要根据系统的实际控制需要而定。 （4）总线带宽： ①、总线带宽指单位时间内总线上可以传输的最大的数据量。 ②、总线带宽（MB/s）=（总线位宽/8）×总线工作频率（MHz）×每个总线周期数据传输的次数。 考向复习提示：存储层级塔式结构与系统总线分类 存储系统按速度由高到低排列为：寄存器 > 高速缓存 Cache > 内存储器（RAM/ROM） > 外存储器（SSD/机械硬盘/光盘）；系统总线按传送信号划分为数据总线（双向传送数据）、地址总线（单向传送物理地址，决定最大寻址空间）、控制总线（双向传送控制/时序信号）。 高频易错陷阱：地址总线宽度与寻址能力计算 若 CPU 的地址总线为 32 位，则其最大可直接寻址空间为 2^32 字节 = 4 GB；若地址总线为 36 位，最大寻址空间为 2^36 字节 = 64 GB；常考陷阱是将寻址空间误算为“字”而非“字节”，计算机内存始终以字节（8 位）为基本编址单位！$kbfixsearch$);
do $$
declare r record; old_rev record; v_rev integer;
begin
  for r in select node_id, blocks, search_text from _kb_fix loop
    select rev_no, html, source_ref into old_rev
      from kb_revision
     where node_id = r.node_id
       and rev_no = (select published_rev from kb_entry where node_id = r.node_id);
    if not found then raise exception 'node % 找不到已发布 revision', r.node_id; end if;
    select coalesce(max(rev_no), 0) + 1 into v_rev from kb_revision where node_id = r.node_id;
    insert into kb_revision(node_id, rev_no, blocks, html, search_text, source_ref)
    values (r.node_id, v_rev, r.blocks, old_rev.html, r.search_text, old_rev.source_ref);
    update kb_entry set published_rev = v_rev, updated_at = now() where node_id = r.node_id;
  end loop;
end $$;
commit;
